REMAINDER_NOTATION=re.compile(r'^\s*[\d,]+\s+R\d+\s*$')
def natural_latin(text):
 text=re.sub(r'(?<![A-Za-z])R(?=\d|\b)','',text)
 text=re.sub(r'(?<![A-Za-z])x(?![A-Za-z])','',text)
 text=re.sub(r'\([ab]\)','',text)
 return bool(re.search('[A-Za-z]',text))
def gather(root):
 # R is the source's explicitly defined mathematical remainder notation,
 # including when represented in CNXML prose. Keep it, like other math tokens.
 return {k:kept for k,v in original_gather(root).items() if (kept:=[s for s in v if natural_latin(s[2])])}
